$ErrorActionPreference='Stop'
$candidates = @(
  'C:\Users\Xxkan\mhw-mods',
  'C:\Users\Xxkan\Desktop\mhw-mods',
  'C:\Users\Xxkan\Documents\mhw-mods',
  'C:\Users\Xxkan\source\repos\mhw-mods',
  'C:\Users\Xxkan\repos\mhw-mods',
  'C:\Users\Xxkan\Projects\mhw-mods'
)
$repo = $null
foreach($p in $candidates){
  if(Test-Path (Join-Path $p '.git')){
    $remote = (& git -C $p remote get-url origin 2>$null)
    if($remote -match 'fengie/mhw-mods'){ $repo=$p; break }
  }
}
if(-not $repo){
  $repo = Get-ChildItem 'C:\Users\Xxkan' -Directory -Recurse -ErrorAction SilentlyContinue |
    Where-Object { $_.Name -eq 'mhw-mods' -and (Test-Path (Join-Path $_.FullName '.git')) } |
    Select-Object -First 1 -ExpandProperty FullName
}
if(-not $repo){ throw 'mhw-mods checkout not found' }
Write-Output ('REPO=' + $repo)
& git -C $repo fetch origin --prune
$branches = & git -C $repo for-each-ref --format='%(refname:short)' refs/remotes/origin |
  Where-Object { $_ -ne 'origin/main' -and $_ -ne 'origin/HEAD' }
foreach($b in $branches){
  $name=$b -replace '^origin/',''
  & git -C $repo merge-base --is-ancestor $b origin/main
  $ancestor = ($LASTEXITCODE -eq 0)
  $cherry = @(& git -C $repo cherry origin/main $b)
  $plus = @($cherry | Where-Object { $_ -like '+ *' }).Count
  $minus = @($cherry | Where-Object { $_ -like '- *' }).Count
  Write-Output (('BRANCH={0}|ANCESTOR={1}|PLUS={2}|MINUS={3}') -f $name,$ancestor,$plus,$minus)
}
